settings.custom_liquid:
{% style %}
  .twint-button-wrapper {
    display: flex;
    justify-content: center;
    align-items: center; /* remove this if you don't need vertical centering */
    width: 100%;
    padding: 5px 0; /* optional spacing */
  }

  .twint-button-wrapper button {
    width: auto;
    height: 58px;
    border-radius: 6px;
    display: flex;
    justify-content: center;
    align-items: center;
    cursor: pointer;
    background-color: transparent;
    border: none;
  }

  .twint-button-wrapper button img {
    width: auto;
    height: 58px;
  }
{% endstyle %}

<div class="twint-button-wrapper">
  <button
    onclick="window.open('https://go.twint.ch/1/e/tw?tw=acq.w37DMR2IQXSZdtJjGHMMb3kDgfKp8wsnDV7xIue7_cGoob1DlBbSyMMTJDokq70l.', '_blank')"
  >
    <img
      alt="Embedded TWINT button"
      src="https://go.twint.ch/static/img/button_dark_en.svg"
    />
  </button>
</div>
